using MediatR;
using Pim.SharedKernel.Results;

namespace Pim.Catalog.Application.AssetLibrary;

/// <summary>
/// Where binaries live.
///
/// The interface exists so the storage decision stays a configuration choice
/// rather than a rewrite. It starts on local disk (decision 2026-08-19); S3 or
/// Azure Blob is a second implementation and a connection string, which is the
/// same seam ADR-007 used for the outbox transport and for the same reason —
/// build the hard half, leave the leaf swappable.
///
/// Keys are generated by this service and are content-addressed. No key ever
/// comes from a caller, which is what keeps path traversal out of the design
/// rather than out of a validator.
/// </summary>
public interface IAssetStorage
{
    /// <summary>Value recorded in `asset.storage_provider`, e.g. "local".</summary>
    string ProviderName { get; }

    Task SaveAsync(string key, Stream content, CancellationToken cancellationToken);

    /// <summary>Null when the key is not present.</summary>
    Task<Stream?> OpenReadAsync(string key, CancellationToken cancellationToken);

    Task<bool> ExistsAsync(string key, CancellationToken cancellationToken);
}

/// <summary>One generated derivative, still in memory.</summary>
public sealed record GeneratedRendition(
    string Role,
    byte[] Content,
    int Width,
    int Height,
    string Format);

/// <summary>The original's own dimensions, when they can be read.</summary>
public sealed record ImageProbe(int Width, int Height);

/// <summary>
/// Makes the derivatives a storefront actually consumes.
///
/// Only images produce anything. BIM, CAD and documents are stored and served
/// as opaque binaries by decision (2026-08-19): rendering IFC, RVT or DWG needs
/// a CAD toolchain with its own licence and cost, and a preview nobody can
/// trust is worse than a file icon.
/// </summary>
public interface IRenditionGenerator
{
    /// <summary>
    /// Reads the stream from position 0 and returns the derivatives to store.
    /// Empty for anything that is not a decodable image — which is a fact about
    /// the input, not a failure.
    /// </summary>
    Task<IReadOnlyList<GeneratedRendition>> GenerateAsync(
        Stream original, string assetType, CancellationToken cancellationToken);

    /// <summary>Null when the stream is not a decodable image.</summary>
    Task<ImageProbe?> ProbeAsync(Stream original, CancellationToken cancellationToken);
}

/// <summary>An asset row as the ingest path needs to see it.</summary>
public sealed record IngestedAsset(Guid PublicId, bool Deduplicated);

/// <summary>Everything the ingest handler needs to persist, in one transaction.</summary>
public sealed record AssetIngestRequest(
    string StorageProvider,
    string StorageKey,
    string FileName,
    string? MimeType,
    string AssetType,
    long FileSizeBytes,
    string Checksum,
    int? Width,
    int? Height,
    string? UsageRights,
    DateOnly? RightsExpiry,
    string? Title,
    string? AltText,
    string LocaleCode,
    IReadOnlyList<StoredRendition> Renditions);

/// <summary>A rendition after it has been written to storage.</summary>
public sealed record StoredRendition(string Role, string Uri, int? Width, int? Height, string? Format);

public interface IAssetIngestStore
{
    /// <summary>The public id of an active asset with this checksum, or null.</summary>
    Task<Guid?> FindByChecksumAsync(string checksum, CancellationToken cancellationToken);

    Task<Guid> InsertAsync(AssetIngestRequest request, CancellationToken cancellationToken);

    /// <summary>Storage provider, key and format for one rendition — for serving.</summary>
    Task<AssetBinaryLocation?> FindBinaryAsync(
        Guid publicId, string renditionRole, CancellationToken cancellationToken);
}

public sealed record AssetBinaryLocation(
    string StorageProvider,
    string Uri,
    string? MimeType,
    string? FileName);

/// <summary>
/// Upload one file.
/// </summary>
/// <param name="Content">
/// Read once, streamed, never buffered whole: a 500 MB Revit family must not
/// become 500 MB of managed heap.
/// </param>
public sealed record UploadAssetCommand(
    Stream Content,
    string FileName,
    string? ContentType,
    string? AssetType,
    string? Title,
    string? AltText,
    string? UsageRights,
    DateOnly? RightsExpiry,
    string? Locale) : IRequest<Result<IngestedAsset>>;
